lessons.codeExample:
#include <iostream>
using namespace std;

class Vehicle {
public:
    string brand = "Ford";
    void honk() { cout << "Tuut!\n"; }
};

// Truck inherits from Vehicle
class Truck : public Vehicle {
public:
    int cargoCapacity = 5000;
};

int main() {
    Truck myTruck;
    myTruck.honk(); // Method from parent
    cout << myTruck.brand << " cap: " << myTruck.cargoCapacity;
    return 0;
}

